from pathlib import Path
from fractions import Fraction as F
import json
B=Path(__file__).resolve().parent
O=B/'company-video-grammar-analyzer-workspace/iteration-2/eval-V05/with_skill/outputs'
plan=json.loads((B/'case-plan.json').read_text(encoding='utf-8'))
case=next(x for x in plan['cases'] if x['case_id']=='V05')
logs=[B/'cases/A4-G/V05/실행기록.json',B/'cases/A4-G/V05_retest_more/실행기록.json']
frames={float(F(f['actual_playback_seconds'])):f for l in logs for f in json.loads(l.read_text(encoding='utf-8'))['frames']}
def key(t):return min(frames,key=lambda v:abs(v-t))
def eid(t):return 'f'+str(round(key(t)*1000))
used=set();objs=[]
def ev(desc,prop,ts,order,kind='unknown',basis='표본에서 변화의 존재·방향을 확인했으나 같은 속성의 진행량을 충분히 측정하지 않아 곡선은 미확정.',limits=None,status='observed',measure=None):
    used.update(key(t) for t in ts)
    d={'description':desc,'properties':[prop],'time_seconds':[min(ts),max(ts)],'evidence_ids':[eid(t) for t in ts],'direction_order':order,'easing':{'property':prop,'classification':kind,'basis':basis},'status':status,'limitations':limits or []}
    if measure:d['easing']['measurements']=measure
    return d
